public record Point(int x, int y) implements Comparable<Point> {
    // compiler tự sinh:
    //   private final int x; private final int y;
    //   public Point(int x, int y) { this.x = x; this.y = y; }
    //   public int x(); public int y();
    //   equals / hashCode / toString

    static final Point ORIGIN = new Point(0, 0); // static field: OK
    // private int cache;                        // instance field: LỖI BIÊN DỊCH

    public static Point of(int x, int y) { return new Point(x, y); }

    @Override public int compareTo(Point o) {
        return Integer.compare(x * x + y * y, o.x * o.x + o.y * o.y);
    }
}

Point p = new Point(1, 2);
System.out.println(p.x());      // 1  -- KHÔNG phải getX()
