public record Money(String currency, long amount) {
    // compact constructor: KHÔNG có danh sách tham số
    public Money {
        Objects.requireNonNull(currency, "currency");
        if (amount < 0) throw new IllegalArgumentException("amount < 0");
        currency = currency.toUpperCase(); // chuẩn hoá THAM SỐ
        // this.currency = currency;  <-- LỖI BIÊN DỊCH
        // compiler chèn ngầm: this.currency = currency; this.amount = amount;
    }

    // constructor thay thế: bắt buộc uỷ quyền về canonical
    public Money(String currency) {
        this(currency, 0L);
    }
}

new Money("usd", 10);   // Money[currency=USD, amount=10]
new Money("usd", -1);   // IllegalArgumentException

