// Local record trong stream pipeline (Java 16+)
List<String> topByScore(List<String> words) {
    record Scored(String word, int score) {}   // record cục bộ trong method
    return words.stream()
        .map(w -> new Scored(w, expensiveScore(w)))  // tính điểm đúng một lần
        .sorted(Comparator.comparingInt(Scored::score).reversed())
        .limit(10)
        .map(Scored::word)
        .toList();
}

