// Java 21: sealed + record + pattern switch
sealed interface Shape permits Circle, Rect, Tri {}
record Circle(double r) implements Shape {}
record Rect(double w, double h) implements Shape {}
record Tri(double b, double h) implements Shape {}

static double area(Shape s) {
    return switch (s) {                 // KHÔNG có default
        case Circle c -> Math.PI * c.r() * c.r();
        case Rect r   -> r.w() * r.h();
        case Tri t    -> t.b() * t.h() / 2;
    };
}
// Thêm 'record Square(double a) implements Shape' vào permits
// -> area() lập tức LỖI BIÊN DỊCH: "the switch expression does not cover all possible input values"

