// Cũ: dạng hai chấm, có fall-through
int r = 0;
switch (x) {
    case 1: r += 1;      // KHÔNG có break -> rơi xuống case 2
    case 2: r += 2; break;
    default: r += 10;
}
// x = 1  ->  r = 3

// Mới: dạng mũi tên, không fall-through
int r2 = 0;
switch (x) {
    case 1 -> r2 += 1;
    case 2 -> r2 += 2;
    default -> r2 += 10;
}
// x = 1  ->  r2 = 1

// switch expression + yield
int days = switch (month) {
    case JAN, MAR, MAY, JUL, AUG, OCT, DEC -> 31;
    case APR, JUN, SEP, NOV -> 30;
    case FEB -> {
        int base = 28;
        yield isLeap(year) ? base + 1 : base;   // return ở đây là LỖI BIÊN DỊCH
    }
};  // enum liệt kê đủ -> không cần default

static String describe(Object o) {
    return switch (o) {
        case null                    -> "khong co gi";     // không có dòng này -> NPE khi o == null
        case Integer i when i > 100  -> "so lon: " + i;    // guarded: phải đứng trước case Integer i
        case Integer i               -> "so: " + i;
        case String s                -> "chuoi dai " + s.length();
        case int[] arr               -> "mang " + arr.length + " phan tu";
        default                      -> "kieu khac";
    };
}

describe(null);   // "khong co gi"
describe(500);    // "so lon: 500"
describe(5);      // "so: 5"

