// 1) if-else instanceof: không ai kiểm tra hộ bạn
static double areaOld(Shape s) {
    if (s instanceof Circle c) return Math.PI * c.r() * c.r();
    else if (s instanceof Rect r) return r.w() * r.h();
    else throw new IllegalStateException("quen mot bien the?"); // lỗi lúc CHẠY
}

// 2) pattern switch trên sealed: lỗi lúc BIÊN DỊCH nếu thiếu nhánh
static double area(Shape s) {
    return switch (s) {
        case Circle c -> Math.PI * c.r() * c.r();
        case Rect r   -> r.w() * r.h();
    };
}

